/* NMWDI theme: the New Mexico Water Data Initiative palette (teal,
   terracotta, sand), used by Weaver. Values not specific to NMWDI (page
   background, foreground, light surfaces, radius, fonts) match Ocotillo.
   Defines the whole token contract (see THEMING.md). */

:root[data-theme="nmwdi"] {
    --background: #e7e5e4; /* stone-200 (page) */
    --foreground: #0f172a; /* slate-900 */
    --card: #ffffff; /* paper */
    --card-foreground: #0f172a;
    --popover: #ffffff;
    --popover-foreground: #0f172a;

    --primary: #006d8b; /* NMWDI teal */
    --primary-foreground: #ffffff;
    --primary-light: #a6ccd6; /* NMWDI light teal */
    --primary-dark: #004153; /* NMWDI deep teal */

    --secondary: #b1422f; /* NMWDI terracotta */
    --secondary-foreground: #ffffff;
    --secondary-strong: #8f3526;
    --secondary-dark: #6f291d;

    --muted: #f1f5f6; /* cool teal-tinted wrapper */
    --muted-foreground: #4b6470; /* slate-teal */
    --accent: #e7f0f2; /* light teal tint */
    --accent-foreground: #04323f;
    --destructive: #b1422f; /* terracotta (brand red) */
    --warning-light: #fdba74; /* orange-300 */
    --warning-dark: #c2410c; /* orange-700 */

    --border: #cdd9dc; /* cool teal-gray */
    --input: #cdd9dc;
    --ring: #006d8b;

    --chart-1: #006d8b; /* teal */
    --chart-2: #b1422f; /* terracotta */
    --chart-3: #4a98ab; /* mid teal */
    --chart-4: #e0a458; /* sand */
    --chart-5: #6f8a93; /* slate-teal */

    --radius: 0.5rem;

    --sidebar: #ffffff;
    --sidebar-foreground: #04323f;
    --sidebar-primary: #006d8b;
    --sidebar-primary-foreground: #ffffff;
    --sidebar-accent: #e7f0f2;
    --sidebar-accent-foreground: #04323f;
    --sidebar-border: #cdd9dc;
    --sidebar-ring: #006d8b;

    --font-heading: 'Outfit Variable', system-ui, sans-serif;
    --font-sans: 'Public Sans Variable', system-ui, sans-serif;
}

:root[data-theme="nmwdi"].dark {
    /* Surfaces sit one small step above the page, in the theme's teal-slate.
       Ocotillo's dark card (zinc-700) is two steps up and equals --border. */
    --background: #18181b; /* zinc-900 (default) */
    --foreground: #f1f5f9; /* slate-100 */
    --card: #1f2a2e;
    --card-foreground: #f1f5f9;
    --popover: #1f2a2e;
    --popover-foreground: #f1f5f9;

    --primary: #3aa3c0; /* NMWDI teal (brighter on dark) */
    --primary-foreground: #04222b;
    --primary-light: #a6ccd6; /* NMWDI light teal */
    --primary-dark: #004153; /* NMWDI deep teal */

    --secondary: #cf6a57; /* NMWDI terracotta (brighter on dark) */
    --secondary-foreground: #2a0f0a;
    --secondary-strong: #b1422f;
    --secondary-dark: #8f3526;

    --muted: #27272a; /* zinc-800 */
    --muted-foreground: #b6c6cb; /* light slate-teal: 8.3:1 on card, 10:1 on page */
    --accent: #2a3b40; /* dark teal tint */
    --accent-foreground: #e7f0f2;
    --destructive: #e06a56; /* terracotta (brighter on dark) */
    --warning-light: #fdba74; /* orange-300 */
    --warning-dark: #c2410c; /* orange-700 */

    --border: #3a4348; /* cool teal-gray divider */
    --input: #3a4348;
    --ring: #3aa3c0;

    --chart-1: #5cb8d4; /* teal */
    --chart-2: #e08a78; /* terracotta */
    --chart-3: #a6ccd6; /* light teal */
    --chart-4: #e8bd86; /* sand */
    --chart-5: #9aafb6; /* slate-teal */

    --sidebar: #1f2a2e; /* dark teal-slate */
    --sidebar-foreground: #e7f0f2;
    --sidebar-primary: #3aa3c0;
    --sidebar-primary-foreground: #04222b;
    --sidebar-accent: #2a3b40;
    --sidebar-accent-foreground: #e7f0f2;
    --sidebar-border: #3a4348;
    --sidebar-ring: #3aa3c0;
}
